    def test_final_support_failure_consumes_without_features_or_partial_inference(self):
        from contextlib import ExitStack
        with ExitStack() as stack:
            _, session, materializer, extractor, _, _, written = self.setup_mocks(stack)
            original = materializer.side_effect
            def fail_final(*args):
                original(*args)
                if args[-1]:
                    raise execution.ExecutionContractError("SYNTHETIC_FINAL_SUPPORT")
                return {s["sample_id"]: "synthetic" for s in args[0]}
            materializer.side_effect = fail_final
            self.assertEqual(runner.main(), 2)
            extractor.assert_called_once()
            session.infer.assert_not_called()
            session.score.assert_not_called()
            self.assertEqual(materializer.call_count, 2)
        result = written["results.json"]
        self.assertEqual(result["ML_FINAL_TEST"], "CONSUMED")
        self.assertEqual(result["TI3_D_FINAL"], "BLOCKED_FINAL_SUPPORT_OR_INTEGRITY")
        self.assertFalse(result["ML_FINAL_TEST_EXECUTED"])

    def test_prediction_freeze_failure_denies_scoring_and_retry(self):
        from contextlib import ExitStack
        with ExitStack() as stack:
            _, session, _, _, _, _, written = self.setup_mocks(stack)
            session.freeze_predictions.side_effect = OSError("synthetic prediction write failure")
            self.assertEqual(runner.main(), 2)
            session.fit.assert_called_once()
            session.infer.assert_called_once()
            session.score.assert_not_called()
        self.assertEqual(written["results.json"]["FINAL_EVALUATIONS"], 0)
        self.assertEqual(written["results.json"]["ML_FINAL_TEST"], "CONSUMED")

    def test_one_support_phase_before_all_feature_processing(self):
        np = mock.Mock()
        reader = mock.Mock()
        samples = [{"sample_id": str(i), "split": "FINAL_TEST", "source_id": "ESM1", "frame_index": 293}
                   for i in range(6)]
        images = [{"source_id": "ESM1", "frame_index": 293}, {"source_id": "ESM2", "frame_index": 293}]
        with mock.patch.object(runner, "checked_luminance", side_effect=ValueError("synthetic support")), \
             mock.patch.object(runner, "multimodal_features") as feature:
            with self.assertRaises(ValueError):
                runner.materialize_patches(samples, images, reader, {}, [], True)
            feature.assert_not_called()
            reader.read_native.assert_called_once()


